type Onboarding = {
  account: { email: string; password: string };
  profile: { name: string; company: string };
  plan: { tier: 'free' | 'pro'; billing: 'monthly' | 'yearly' };
};

const stepFields = {
  0: ['account.email', 'account.password'],
  1: ['profile.name', 'profile.company'],
  2: ['plan.tier', 'plan.billing'],
} as const;

import { useState } from 'react';
import { z } from 'zod';
import { zodResolver } from 'qortex-resource';
import { createResourceHooks } from 'qortex-resource-react';

const Schema = z.object({
  account: z.object({
    email: z.string().email(),
    password: z.string().min(8),
  }),
  profile: z.object({
    name: z.string().min(1),
    company: z.string().min(1),
  }),
  plan: z.object({
    tier: z.enum(['free', 'pro']),
    billing: z.enum(['monthly', 'yearly']),
  }),
});

const { useResource, useField } = createResourceHooks({
  key: ['onboarding'],
  initialData: {
    account: { email: '', password: '' },
    profile: { name: '', company: '' },
    plan: { tier: 'free', billing: 'monthly' },
  } satisfies Onboarding,
  validate: { resolver: zodResolver(Schema), on: 'manual' },
  persist: { draft: true, debounce: 300 },
  source: {
    save: (draft) => api.onboarding.complete(draft),
  },
});

export function OnboardingWizard() {
  const { validateFields, save, isSaving, resetDraft } = useResource();
  const [step, setStep] = useState(0);

  async function next() {
    const paths = [...stepFields[step as 0 | 1 | 2]];
    const ok = await validateFields(paths);
    if (!ok) return;
    if (step < 2) setStep((s) => s + 1);
    else await save();
  }

  return (
    <div>
      <ol>
        <li data-active={step === 0}>Account</li>
        <li data-active={step === 1}>Profile</li>
        <li data-active={step === 2}>Plan</li>
      </ol>

      {step === 0 && <AccountStep />}
      {step === 1 && <ProfileStep />}
      {step === 2 && <PlanStep />}

      <div>
        <button type="button" disabled={step === 0} onClick={() => setStep((s) => s - 1)}>
          Back
        </button>
        <button type="button" disabled={isSaving} onClick={next}>
          {step < 2 ? 'Continue' : isSaving ? 'Submitting…' : 'Finish'}
        </button>
        <button type="button" onClick={resetDraft}>Reset</button>
      </div>
    </div>
  );
}

function AccountStep() {
  const email = useField('account.email');
  const password = useField('account.password');
  return (
    <>
      <input value={email.value ?? ''} onChange={(e) => email.onChange(e.target.value)} onBlur={email.onBlur} />
      {email.error}
      <input type="password" value={password.value ?? ''} onChange={(e) => password.onChange(e.target.value)} onBlur={password.onBlur} />
      {password.error}
    </>
  );
}

function ProfileStep() {
  const name = useField('profile.name');
  const company = useField('profile.company');
  return (
    <>
      <input value={name.value ?? ''} onChange={(e) => name.onChange(e.target.value)} onBlur={name.onBlur} />
      {name.error}
      <input value={company.value ?? ''} onChange={(e) => company.onChange(e.target.value)} onBlur={company.onBlur} />
      {company.error}
    </>
  );
}

function PlanStep() {
  const tier = useField('plan.tier');
  return (
    <select value={tier.value ?? 'free'} onChange={(e) => tier.onChange(e.target.value)}>
      <option value="free">Free</option>
      <option value="pro">Pro</option>
    </select>
  );
}
